	Tool::~Tool()
	{
		RBXASSERT(!handleTouched.connected());
		RBXASSERT(!characterChildAdded.connected());
		RBXASSERT(!characterChildRemoved.connected());
		RBXASSERT(!torsoChildAdded.connected());
		RBXASSERT(!torsoChildRemoved.connected());
	}

	//99.46% match
