	void Tool::upTo_InWorkspace() {}
	void Tool::upTo_Activated() {}
	void Tool::downFrom_InWorkspace() {}
	void Tool::downFrom_Activated() {}
	void Tool::downFrom_HasHandle() { handleTouched.disconnect(); }

	void Tool::setDesiredState(ToolState desiredState, const ServiceProvider* serviceProvider)
	{
		do
		{
			if (backendToolState < desiredState)
			{
				switch (backendToolState)
				{
				case HAS_TORSO:
					upTo_Equipped();
					break;
				case IN_CHARACTER:
					upTo_HasTorso();
					break;
				case IN_WORKSPACE:
					upTo_InCharacter();
					break;
				case HAS_HANDLE:
					upTo_InWorkspace();
					break;
				case NOTHING:
					connectTouchEvent();
					break;
				case EQUIPPED:
					upTo_Activated();
					break;
				case ACTIVATED:
					upTo_Activated();
					break;
				}
				setBackendToolState(backendToolState + 1);
			}
			else if (desiredState < backendToolState)
			{
				switch (backendToolState)
				{
				case EQUIPPED:
					downFrom_Equipped();
					break;
				case HAS_TORSO:
					downFrom_HasTorso();
					break;
				case IN_CHARACTER:
					downFrom_InCharacter();
					break;
				case IN_WORKSPACE:
					downFrom_InWorkspace();
					break;
				case HAS_HANDLE:
					downFrom_HasHandle();
					break;
				case NOTHING:
					downFrom_InWorkspace();
					break;
				}
				setBackendToolState(backendToolState - 1);
			}
		} while (desiredState != backendToolState);
	}
}

